/* 1) 高亮所有天花板 (pulse 闪烁) */
const list = ssp.objectsTool.getByUserDataProperty('renderType', 'CEILING');
list.forEach(o => ssp.objectsTool.setHighlight(o, '#ff0000', true));
console.log(`highlighted ${list.length} CEILING`);

/* 2) 高亮 + 飞到第一个对象 */
const list2 = ssp.objectsTool.getByUserDataProperty('renderType', 'CEILING');
list2.forEach(o => ssp.objectsTool.setHighlight(o, '#ff0000', true));
if (list2.length > 0) await ssp.cameraController.flyToObject(list2[0]);

/* 3) 高亮所有窗户 (静态, 不闪烁) */
const windows = ssp.objectsTool.getByUserDataProperty('renderType', 'WINDOW');
windows.forEach(o => ssp.objectsTool.setHighlight(o, '#29ccff'));

/* 4) 限定 scope (只搜 hospital 子目录) */
const toilets = ssp.objectsTool.getByUserDataProperty('spaceType', 'TOILET', { scope: 'hospital' });
toilets.forEach(o => ssp.objectsTool.setHighlight(o, '#00ff00', true));

